    for (int i = 0; i < n; i++) {
        adj[i] = new int[degree[i]];
    }
    int[] idx = new int[n];
    for (int[] e : edges) {
        int u = e[0], v = e[1];
        adj[u][idx[u]++] = v;
        adj[v][idx[v]++] = u;
    }

    // iterative DFS to capture order
    int[] parent = new int[n];
    for (int i = 0; i < n; i++) parent[i] = -1;
    int[] stack = new int[n];
    int top = 0;
    stack[top++] = 0;
    int[] order = new int[n];
    int orderSize = 0;
    while (top > 0) {
        int node = stack[--top];
        order[orderSize++] = node;
        for (int nei : adj[node]) {
            if (nei != parent[node]) {
                parent[nei] = node;
                stack[top++] = nei;
            }
        }
    }

    int[] time = new int[n];
    for (int i = orderSize - 1; i >= 0; i--) {
        int node = order[i];
        for (int nei : adj[node]) {
            if (nei != parent[node]) {
                if (time[nei] > 0 || hasApple[nei]) {
                    time[node] += time[nei] + 2;
                }
            }
        }
    }
    return time[0];
}

