        remaining--;
        decrement(freq, max);
        curr = max;
        while (true) {
            Character prev = freq.lowerKey(curr);
            if (prev == null) break;
            sb.append(prev);
            remaining--;
            decrement(freq, prev);
            curr = prev;
        }
    }
    return sb.toString();
}

